export function reviewedCiDtoReplacements(
  declarations: readonly DtoDeclaration[],
): readonly DtoDeclaration[] {
  const replacements = new Map<
    string,
    (typeof REVIEWED_CI_DTO_REPLACEMENTS)[number]
  >(REVIEWED_CI_DTO_REPLACEMENTS.map((entry) =>
    [entry.locator, entry] as const));
  const seen = new Set<string>();
  const retained = declarations.map((declaration) => {
    const replacement = replacements.get(declaration.locator);
    if (replacement === undefined) return declaration;
    if (seen.has(declaration.locator)) {
      throw new Error(`CI DTO predecessor is ambiguous: ${declaration.locator}`);
    }
    seen.add(declaration.locator);
    const received = declarationDigest(declaration);
    if (received !== replacement.predecessorSha256) {
      throw new Error(
        `CI DTO predecessor changed for ${declaration.locator}: expected ${replacement.predecessorSha256}, received ${received}`,
      );
    }
    return replacement.declaration;
  });
  const missing = REVIEWED_CI_DTO_REPLACEMENTS
    .filter((entry) => !seen.has(entry.locator))
    .map((entry) => entry.locator);
  if (missing.length > 0) {
    throw new Error(`CI DTO predecessors are missing: ${missing.join(", ")}`);
  }
  const existing = new Set(retained.map((entry) => entry.locator));
  const colliding = REVIEWED_CI_NEW_DTO_DECLARATIONS
    .filter((entry) => existing.has(entry.locator))
    .map((entry) => entry.locator);
  if (colliding.length > 0) {
    throw new Error(`CI DTO additions already exist: ${colliding.join(", ")}`);
  }
  return [...retained, ...REVIEWED_CI_NEW_DTO_DECLARATIONS];
}
